#!/usr/bin/env node
/**
 * Generate the Blume site pages (`docs/ablo/*.mdx`) from the canonical SDK
 * markdown docs (`packages/sync-engine/docs/*.md`).
 *
 * The package docs are the single source of truth -- they ship in the npm tarball
 * and are guarded by `check-doc-drift.mjs`. The site tree is a pure projection of
 * the package docs: edit the `.md`, run `npm run build:docs`, and the `.mdx`
 * follows.
 *
 * Scope: the 1:1 prose pages only. Two site pages are generated by their own
 * pipelines and are left alone here -- `errors.mdx` (generate-error-docs.mts) and
 * the changelog (built from CHANGELOG.md, below). `openapi.json` and the few
 * hand-written pages without a `.md` source are also left untouched.
 *
 * Transform per file: drop the leading H1 (Blume renders the frontmatter title as
 * the page heading), rewrite Mintlify callout components (`<Note>`, `<Warning>`,
 * `<Tip>`, `<Info>`) to Blume's `:::directive` syntax, escape MDX-hostile prose
 * (bare `<`/`{`/`}` outside code -- Blume compiles `.mdx` through Astro/MDX, which
 * reads those as JSX), and prepend frontmatter + a "do not edit" banner. Run with
 * `--check` to fail when the on-disk `.mdx` is stale (used by `lint:docs-site`).
 */

import { readFileSync, writeFileSync, mkdirSync, rmSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { execFileSync } from 'node:child_process';

const packageRoot = resolve(fileURLToPath(new URL('..', import.meta.url)));
const repoRoot = resolve(packageRoot, '..', '..');
const SRC = resolve(packageRoot, 'docs');
// The Blume site lives at `docs/ablo/` (project root: blume.config.ts + package.json);
// its content root is the nested `docs/` folder Blume scans by default.
const OUT = resolve(repoRoot, 'docs', 'ablo', 'docs');
const CHANGELOG_DIR = resolve(OUT, 'changelog');

// slug -> curated site page title (preserved from the prior hand-written pages;
// the package-doc H1s differ, e.g. "Coordination Reference" vs the site's
// "Coordination"). Only slugs listed here are generated.
const TITLES = {
  api: 'API',
  coordination: 'Coordination',
  quickstart: 'Quickstart',
  'how-it-works': 'How Ablo Works',
  react: 'React',
  guarantees: 'Guarantees',
  migration: 'Version History & Migration Guide',
  'interaction-model': 'Interaction Model',
  'client-behavior': 'Client Behavior',
  cli: 'CLI',
  audit: 'Audit log',
  'data-sources': 'Connect Your Database',
  'integration-guide': 'Integration Guide',
  index: 'Ablo Docs',
  'api-keys': 'API Keys',
  mcp: 'Model Context Protocol',
  identity: 'Identity & Sync Groups',
  groups: 'Change Propagation',
  'concurrency-convention': 'Concurrency Convention',
  'schema-contract': 'Schema Contract',
  sessions: 'Sessions',
  agents: 'Agents',
  webhooks: 'Webhooks',
  projects: 'Projects',
  'agent-messaging': 'Agent Messaging',
};

// Optional `description` frontmatter, preserved for pages that had one.
const DESCRIPTIONS = {
  sessions:
    'Short-lived, scoped credentials your backend mints -- one resource for both end-user browser sessions and scoped agents.',
  projects:
    'One organization, many apps -- each project has its own schema, its own data planes, and its own keys.',
};

// Mintlify callout components -> Blume block directives. The source docs author
// callouts as block-level tags on their own lines (`<Note>` ... `</Note>`), so a
// plain tag swap is safe -- the content in between is untouched.
const CALLOUTS = { Note: 'note', Warning: 'warning', Tip: 'tip', Info: 'info' };

function rewriteCallouts(text) {
  let out = text;
  for (const [tag, kind] of Object.entries(CALLOUTS)) {
    out = out
      .replace(new RegExp(`<${tag}>`, 'g'), `:::${kind}`)
      .replace(new RegExp(`</${tag}>`, 'g'), ':::');
  }
  return out;
}

/**
 * Escape MDX-hostile chars in a prose segment (never inside code). Lowercase
 * angle-brackets (`<model>`, `<your_db>`) are placeholders and get escaped so
 * MDX doesn't read them as tags; `{`/`}` are escaped so MDX doesn't read them as
 * expressions. Callouts have already been rewritten to `:::` directives, so no
 * PascalCase component tags survive into this step.
 */
function escapeProse(text) {
  return text
    .replace(/<(?![A-Z]|\/[A-Z])/g, '&lt;') // escape `<` unless it opens/closes a component
    .replace(/\{/g, '&#123;')
    .replace(/\}/g, '&#125;');
}

/**
 * Split markdown into fenced-code blocks (passed through verbatim) and
 * everything else (prose, where inline-code spans are also protected).
 */
function transform(md, slug) {
  // 1. Pull out fenced code blocks so their contents are never escaped.
  const fences = [];
  let body = md.replace(/```[\s\S]*?```/g, (m) => {
    fences.push(m);
    return ` FENCE${fences.length - 1} `;
  });

  // 2. Drop the leading H1 -- the frontmatter title becomes the page heading.
  body = body.replace(/^\s*#\s+.*\n+/, '');

  // 2b. Link rewriting for the site.
  const GH = 'https://github.com/Abloatai/ablo/blob/main';
  body = body
    // Repo-root files that aren't site pages -> GitHub; the changelog -> its page.
    .replace(
      /\]\((?:\.\.?\/)*(README|AGENTS)\.md(#[A-Za-z0-9_-]+)?\)/g,
      (_, name, anchor = '') => `](${GH}/${name}.md${anchor})`,
    )
    .replace(/\]\((?:\.\.?\/)*CHANGELOG\.md\)/g, '](/changelog)')
    // Some source links carry a `/docs` base path; the site serves at root.
    .replace(/\]\(\/docs\//g, '](/')
    // Relative `.md` links -> site routes (extensionless, root-relative):
    // `[x](./foo.md#a)` / `[x](foo.md)` -> `[x](/foo#a)`.
    .replace(
      /\]\((?:\.\/|\.\.\/)?([A-Za-z0-9_/-]+)\.md(#[A-Za-z0-9_-]+)?\)/g,
      (_, path, anchor = '') => `](/${path}${anchor})`,
    );

  // 2c. Mintlify callout components -> Blume `:::` directives.
  body = rewriteCallouts(body);

  // 3. Escape prose, protecting inline-code spans (which may span newlines).
  body = body
    .split(/(`[^`]*`)/)
    .map((seg) => (seg.startsWith('`') && seg.endsWith('`') ? seg : escapeProse(seg)))
    .join('');

  // 4. Restore fenced code blocks.
  body = body.replace(/ FENCE(\d+) /g, (_, i) => fences[Number(i)]);

  const title = TITLES[slug];
  const descLine = DESCRIPTIONS[slug] ? `description: ${JSON.stringify(DESCRIPTIONS[slug])}\n` : '';
  const frontmatter = `---\ntitle: ${JSON.stringify(title)}\n${descLine}---\n\n`;
  return frontmatter + body.replace(/^\n+/, '').replace(/\s+$/, '') + '\n';
}

/** Hard check: no residual MDX-hostile chars outside code/frontmatter. */
function validate(mdx, label) {
  const fences = [];
  let body = mdx.replace(/```[\s\S]*?```/g, (m) => {
    fences.push(m);
    return '';
  });
  body = body.replace(/^---\n[\s\S]*?\n---\n/, ''); // strip frontmatter
  body = body.replace(/\{\/\*[\s\S]*?\*\/\}/g, ''); // strip MDX comments (banner)
  const prose = body.replace(/`[^`]*`/g, '');
  // A lowercase `<tag` is a placeholder MDX would choke on; PascalCase `<Tag`
  // is an intentional component and is allowed.
  const badLt = prose.match(/<[a-z]/g);
  const badBrace = prose.match(/[{}]/g);
  const problems = [];
  if (badLt) problems.push(`${badLt.length} bare lowercase '<' (would parse as JSX)`);
  if (badBrace) problems.push(`${badBrace.length} bare '{' or '}' (would parse as JSX expression)`);
  if (problems.length) throw new Error(`${label}: ${problems.join('; ')}`);
}

/** Convert a markdown body to an MDX-safe body (fence- and inline-code-aware). */
function escapeMdxBody(md) {
  const fences = [];
  let body = md.replace(/```[\s\S]*?```/g, (m) => {
    fences.push(m);
    return ` FENCE${fences.length - 1} `;
  });
  body = body
    .split(/(`[^`]*`)/)
    .map((seg) => (seg.startsWith('`') && seg.endsWith('`') ? seg : escapeProse(seg)))
    .join('');
  return body.replace(/ FENCE(\d+) /g, (_, i) => fences[Number(i)]);
}

/** Release dates from the `release(sync-engine): X.Y.Z` commits (CHANGELOG.md
 *  carries no dates). `version -> "YYYY-MM-DD"`; absent when no such commit. */
function releaseDates() {
  const map = {};
  let log;
  try {
    log = execFileSync('git', ['log', '--all', '--date=short', '--pretty=%ad%x09%s'], {
      cwd: repoRoot,
      encoding: 'utf8',
      maxBuffer: 32 * 1024 * 1024,
    });
  } catch {
    return map; // no git context -> entries fall back to filesystem order
  }
  for (const line of log.split('\n')) {
    const tab = line.indexOf('\t');
    if (tab < 0) continue;
    const m = line.slice(tab + 1).match(/release\(sync-engine\):\s*(\d+\.\d+\.\d+)/);
    if (m && !map[m[1]]) map[m[1]] = line.slice(0, tab);
  }
  return map;
}

/** The changelog category shown next to each entry's date, derived from the
 *  highest-impact changeset heading in the section. */
function changelogCategory(body) {
  if (/^###\s+Major Changes/m.test(body)) return 'Breaking';
  if (/^###\s+Minor Changes/m.test(body)) return 'Features';
  return 'Fixes';
}

/** One Blume changelog page per `## X.Y.Z` section of CHANGELOG.md. Each page is
 *  `type: changelog`, and Blume assembles them into the `/changelog` timeline. */
function buildChangelogPages() {
  const raw = readFileSync(resolve(packageRoot, 'CHANGELOG.md'), 'utf8');
  const dates = releaseDates();
  return raw
    .split(/^## (?=\d+\.\d+\.\d+)/m)
    .slice(1)
    .map((part) => {
      const nl = part.indexOf('\n');
      const version = part.slice(0, nl).trim().replace(/\s*\(.*\)$/, '');
      // CHANGELOG.md uses the internal package name; the public site uses the
      // published one (the doc-drift lint enforces this for the prose docs).
      const sectionBody = escapeMdxBody(part.slice(nl + 1).trim())
        .replace(/@ablo\/sync-engine/g, '@abloatai/ablo')
        .trim();
      const category = changelogCategory(sectionBody);
      const dateLine = dates[version] ? `date: ${dates[version]}\n` : '';
      const frontmatter =
        `---\n` +
        `title: "v${version}"\n` +
        `type: changelog\n` +
        dateLine +
        `changelog:\n  version: "${version}"\n  category: "${category}"\n` +
        `---\n\n`;
      return { version, content: `${frontmatter}${sectionBody}\n` };
    });
}

const check = process.argv.includes('--check');
const stale = [];
let count = 0;

for (const slug of Object.keys(TITLES)) {
  const srcPath = resolve(SRC, `${slug}.md`);
  let md;
  try {
    md = readFileSync(srcPath, 'utf8');
  } catch {
    throw new Error(`Missing source doc: ${srcPath} (listed in TITLES)`);
  }
  const out = transform(md, slug);
  validate(out, `${slug}.mdx`);
  const outPath = resolve(OUT, `${slug}.mdx`);
  if (check) {
    let current = '';
    try {
      current = readFileSync(outPath, 'utf8');
    } catch {
      /* missing -> stale */
    }
    if (current !== out) stale.push(slug);
  } else {
    writeFileSync(outPath, out);
  }
  count++;
}

// Changelog: one `type: changelog` page per release, assembled into the timeline.
const changelogPages = buildChangelogPages();
if (!check) {
  // Rebuild the folder from scratch so removed releases don't linger.
  rmSync(CHANGELOG_DIR, { recursive: true, force: true });
  mkdirSync(CHANGELOG_DIR, { recursive: true });
}
for (const { version, content } of changelogPages) {
  validate(content, `changelog/${version}.mdx`);
  const pagePath = resolve(CHANGELOG_DIR, `${version}.mdx`);
  if (check) {
    let current = '';
    try {
      current = readFileSync(pagePath, 'utf8');
    } catch {
      /* missing -> stale */
    }
    if (current !== content) stale.push(`changelog/${version}`);
  } else {
    writeFileSync(pagePath, content);
  }
}

if (check) {
  if (stale.length) {
    console.error(
      `[docs] Site pages are stale vs the package docs: ${stale.join(', ')}\n` +
        `       Run \`npm run build:docs\` and commit docs/ablo/**.`,
    );
    process.exit(1);
  }
  console.log(
    `[docs] ${count} pages + ${changelogPages.length} changelog entries in sync with the package docs`,
  );
} else {
  console.log(
    `[docs] generated ${count} pages + ${changelogPages.length} changelog entries -> docs/ablo/`,
  );
}
